import { mockEngine } from "./mock";
import type { Engine, EngineKind } from "./types";

export type { Engine, EngineKind, Level, MarketView, Side } from "./types";

type WasmModule = Engine & { default: () => Promise<unknown> };

// The real module is generated by `make wasm` into src/wasm/. The glob is empty when it is absent.
const wasmModules = import.meta.glob<WasmModule>("../wasm/propamm_wasm.js");

export async function loadEngine(): Promise<{ engine: Engine; kind: EngineKind }> {
  const loader = Object.values(wasmModules)[0];
  if (loader) {
    try {
      const mod = await loader();
      await mod.default();
      return { engine: mod, kind: "wasm" };
    } catch (e) {
      console.warn("WASM load failed, using mock engine", e);
    }
  }
  return { engine: mockEngine, kind: "mock" };
}
